	internal sealed class ActorSessions<T> where T : class, IDisposable
	{
		private readonly Dictionary<NCreature, T> _items = new Dictionary<NCreature, T>(ReferenceEqualityComparer.Instance);

		internal T? First => _items.Values.FirstOrDefault();

		internal int Count => _items.Count;

		internal T? Get(NCreature actor)
		{
			return _items.GetValueOrDefault(actor);
		}

		internal void Add(NCreature actor, T session)
		{
			_items.Add(actor, session);
		}

		internal void Remove(NCreature actor, T session)
		{
			if (Get(actor) == session)
			{
				_items.Remove(actor);
			}
		}

		internal void Reset()
		{
			T[] array = _items.Values.ToArray();
			for (int i = 0; i < array.Length; i++)
			{
				array[i].Dispose();
			}
		}
	}
	internal sealed record AnimationSettings
	{
		internal static AnimationSettings Current { get; set; } = new AnimationSettings();


		public bool ShieldEnabled { get; init; } = true;


		public int ShieldBlockThreshold { get; init; }

		public bool ImperviousEnabled { get; init; } = true;


		public bool SecondWindEnabled { get; init; } = true;


		public bool BrandEnabled { get; init; } = true;


		public bool BattleTranceEnabled { get; init; } = true;


		public bool FeedEnabled { get; init; } = true;


		public bool DemonFormEnabled { get; init; } = true;


		public bool DarkEmbraceEnabled { get; init; } = true;


		public bool ShrugItOffEnabled { get; init; } = true;


		public bool CardWeaponsEnabled { get; init; } = true;


		public bool BarricadeEnabled { get; init; } = true;


		public bool BodySlamEnabled { get; init; } = true;


		public bool BloodFlowEnabled { get; init; } = true;


		public int BodySlamBlockThreshold { get; init; }

		internal bool CanStartBodySlam(int block)
		{
			if (BodySlamEnabled)
			{
				return block >= BodySlamBlockThreshold;
			}
			return false;
		}

		internal bool CanStartShield(int block)
		{
			if (ShieldEnabled && block > 0)
			{
				return block >= ShieldBlockThreshold;
			}
			return false;
		}

		internal bool AllowsCardAction(string animation)
		{
			return animation switch
			{
				"brand" => BrandEnabled, 
				"battle_trance" => BattleTranceEnabled, 
				"feed" => FeedEnabled, 
				"demon_form" => DemonFormEnabled, 
				"dark_embrace" => DarkEmbraceEnabled, 
				"shrug_it_off" => ShrugItOffEnabled, 
				_ => false, 
			};
		}

		[CompilerGenerated]
		private AnimationSettings(AnimationSettings original)
		{
			ShieldEnabled = original.ShieldEnabled;
			ShieldBlockThreshold = original.ShieldBlockThreshold;
			ImperviousEnabled = original.ImperviousEnabled;
			SecondWindEnabled = original.SecondWindEnabled;
			BrandEnabled = original.BrandEnabled;
			BattleTranceEnabled = original.BattleTranceEnabled;
			FeedEnabled = original.FeedEnabled;
			DemonFormEnabled = original.DemonFormEnabled;
			DarkEmbraceEnabled = original.DarkEmbraceEnabled;
			ShrugItOffEnabled = original.ShrugItOffEnabled;
			CardWeaponsEnabled = original.CardWeaponsEnabled;
			BarricadeEnabled = original.BarricadeEnabled;
			BodySlamEnabled = original.BodySlamEnabled;
			BloodFlowEnabled = original.BloodFlowEnabled;
			BodySlamBlockThreshold = original.BodySlamBlockThreshold;
		}

		public AnimationSettings()
		{
		}
	}
