		internal AnimationSettingsStore(string path, Action<string>? reportError = null)
		{
			FilePath = path;
			try
			{
				if (File.Exists(path))
				{
					AnimationSettings animationSettings = JsonSerializer.Deserialize<AnimationSettings>(File.ReadAllText(path)) ?? new AnimationSettings();
					Value = animationSettings with
					{
						ShieldBlockThreshold = Math.Clamp(animationSettings.ShieldBlockThreshold, 0, 40),
						BodySlamBlockThreshold = Math.Clamp(animationSettings.BodySlamBlockThreshold, 0, 50)
					};
				}
			}
			catch (Exception ex) when (((ex is IOException || ex is UnauthorizedAccessException || ex is JsonException) ? 1 : 0) != 0)
			{
				reportError?.Invoke("Cannot read animation settings; using defaults: " + ex.Message);
			}
		}

