				"ShieldEnabled" => Value.ShieldEnabled, 
				"ShieldBlockThreshold" => Value.ShieldBlockThreshold, 
				"ImperviousEnabled" => Value.ImperviousEnabled, 
				"SecondWindEnabled" => Value.SecondWindEnabled, 
				"BrandEnabled" => Value.BrandEnabled, 
				"BattleTranceEnabled" => Value.BattleTranceEnabled, 
				"FeedEnabled" => Value.FeedEnabled, 
				"DemonFormEnabled" => Value.DemonFormEnabled, 
