				"BodySlamBlockThreshold" => Value.BodySlamBlockThreshold, 
				"BodySlamEnabled" => Value.BodySlamEnabled, 
				"BloodFlowEnabled" => Value.BloodFlowEnabled, 
				_ => throw new ArgumentException("Unknown animation setting.", "key"), 
