			(1.46, 1.46),
			(1.64, 1.55),
			(1.8, 1.8),
			(2.0, 2.08),
			(2.2, 2.2),
			(2.48, 2.48)
		});

		private readonly double _duration;

		private readonly double _strength;

		private readonly (double X, double Y)[] _knots;

		private readonly double[] _slopes;

		internal float Duration => (float)_duration;

		private AnimationTempo(double duration, double strength, (double X, double Y)[] knots)
		{
			_duration = duration;
			_strength = strength;
			_knots = knots;
			int num = knots.Length;
			double[] array = new double[num - 1];
			double[] array2 = new double[num - 1];
			_slopes = new double[num];
			for (int i = 0; i < num - 1; i++)
			{
				array[i] = knots[i + 1].X - knots[i].X;
				array2[i] = (knots[i + 1].Y - knots[i].Y) / array[i];
			}
			_slopes[0] = array2[0];
			_slopes[num - 1] = array2[num - 2];
			for (int j = 1; j < num - 1; j++)
			{
				double num2 = 2.0 * array[j] + array[j - 1];
				double num3 = array[j] + 2.0 * array[j - 1];
				_slopes[j] = ((array2[j - 1] * array2[j] <= 0.0) ? 0.0 : ((num2 + num3) / (num2 / array2[j - 1] + num3 / array2[j])));
			}
		}

		internal float Map(float seconds)
		{
			if (seconds <= 0f)
			{
				return 0f;
			}
			if (seconds >= Duration)
			{
				return (float)_knots[^1].Y;
			}
			double num = (double)seconds / _duration * _knots[^1].X;
			int i;
			for (i = 0; _knots[i + 1].X < num; i++)
			{
			}
			double num2 = _knots[i + 1].X - _knots[i].X;
			double num3 = (num - _knots[i].X) / num2;
			double num4 = num3 * num3;
			double num5 = num4 * num3;
			double num6 = (2.0 * num5 - 3.0 * num4 + 1.0) * _knots[i].Y + (num5 - 2.0 * num4 + num3) * num2 * _slopes[i] + (-2.0 * num5 + 3.0 * num4) * _knots[i + 1].Y + (num5 - num4) * num2 * _slopes[i + 1];
			return (float)(num + (num6 - num) * _strength);
		}

		internal float Inverse(float source)
		{
			float num = 0f;
			float num2 = Duration;
			for (int i = 0; i < 32; i++)
			{
				float num3 = (num + num2) * 0.5f;
				if (Map(num3) < source)
				{
					num = num3;
				}
				else
				{
					num2 = num3;
				}
			}
			return (num + num2) * 0.5f;
		}
	}
