		internal void Contacts(BarricadeMotion motion)
		{
			foreach (BarricadeMotion.Contact contact in motion.Contacts)
			{
				if (contact.Time <= _lastContact)
				{
					continue;
				}
				_lastContact = contact.Time;
				Guard(delegate
				{
					if (Play("event:/sfx/enemy/enemy_impact_enemy_size/enemy_impact_armor", 0.45f))
					{
						LandingsStarted++;
					}
				});
			}
		}

