	internal static class DefensePolicy
	{
		private sealed record TurnUse(Creature Player, int Round, int Turn);

		private static readonly ConditionalWeakTable<ICombatState, TurnUse> Uses = new ConditionalWeakTable<ICombatState, TurnUse>();

		private static readonly PropertyInfo? PlayedBy = AccessTools.Property(typeof(CardPlay), "Player");

		internal static void Clear()
		{
			Uses.Clear();
		}

		internal static Player PlayedByPlayer(CardPlay play)
		{
			object? obj = PlayedBy?.GetValue(play);
			return (Player)(((obj is Player) ? obj : null) ?? play.Card.Owner);
		}

		internal static void Record(ICombatState combat, Creature player, int playerTurn)
		{
			Uses.Remove(combat);
			Uses.Add(combat, new TurnUse(player, combat.RoundNumber, playerTurn));
		}

		internal static bool Consume(ICombatState combat, Creature player, int playerTurn)
		{
			bool result = HasPending(combat, player, playerTurn);
			Uses.Remove(combat);
			return result;
		}

		internal static bool HasPending(ICombatState combat, Creature player, int playerTurn)
		{
			if (Uses.TryGetValue(combat, out TurnUse value) && value.Player == player && value.Round == combat.RoundNumber)
			{
				return value.Turn == playerTurn;
			}
			return false;
		}

		internal static bool HasAttackingEnemy(CombatState combat)
		{
			return combat.Enemies.Any(delegate(Creature enemy)
			{
				if (enemy.IsAlive)
				{
					MonsterModel monster = enemy.Monster;
					if (monster != null && monster.IntendsToAttack)
					{
						return !enemy.Monster.SpawnedThisTurn;
					}
				}
				return false;
			});
		}

