		{
			//IL_0008: Unknown result type (might be due to invalid IL or missing references)
			//IL_000e: Invalid comparison between Unknown and I4
			if (!PresentationScope.IsSingleplayer || (int)combat.CurrentSide != 1 || !(play.Card is Impervious))
			{
				return;
			}
			Player val = PlayedByPlayer(play);
			if (PresentationScope.Allows(combat, val.Creature))
			{
				PlayerCombatState playerCombatState = val.PlayerCombatState;
				if (playerCombatState != null)
				{
					Record(combat, val.Creature, playerCombatState.TurnNumber);
				}
			}
		}
	}
