	internal static class OptionalModSettings
	{
		private static bool _watching;

		private static readonly HashSet<string> Attempted = new HashSet<string>();

		internal static bool Available { get; private set; }

		internal static void Install()
		{
			if (_watching)
			{
				return;
			}
			_watching = true;
			AnimationSettings.Current = new AnimationSettings();
			ModManager.OnModDetected += OnModDetected;
			foreach (Mod mod in ModManager.Mods)
			{
				OnModDetected(mod);
			}
		}

		private static void OnModDetected(Mod mod)
		{
			//IL_0037: Unknown result type (might be due to invalid IL or missing references)
			//IL_003d: Invalid comparison between Unknown and I4
			string text = mod.manifest?.id;
			bool flag = ((text == "JmcModLib" || text == "BaseLib") ? true : false);
			if (!flag || (int)mod.state != 1 || !Attempted.Add(text))
			{
				return;
			}
			AnimationSettings current = AnimationSettings.Current;
			try
			{
				Version version = ((text == "BaseLib") ? new Version(3, 4, 7) : new Version(1, 9, 0));
				List<LocString> errors = mod.errors;
				if ((errors != null && errors.Count > 0) || !Version.TryParse(mod.manifest.version?.TrimStart('v', 'V'), out Version result) || result < version)
				{
					Console.WriteLine($"[ShieldOnly] Optional {text} menu needs version {version}+; retaining current animation settings.");
				}
				else
				{
					Assembly assembly = typeof(ModEntry).Assembly;
					string assemblyPath = Path.Combine(Path.GetDirectoryName(assembly.Location), (text == "BaseLib") ? "ShieldOnly.BaseLib.dll" : "ShieldOnly.Settings.dll");
					AssemblyLoadContext.GetLoadContext(assembly).LoadFromAssemblyPath(assemblyPath).GetType((text == "BaseLib") ? "ShieldOnly.BaseLibSettingsMenu" : "ShieldOnly.ModSettingsMenu", throwOnError: true)
						.GetMethod("Install", BindingFlags.Static | BindingFlags.Public)
						.Invoke(null, null);
					Available = true;
					Console.WriteLine("[ShieldOnly] Optional " + text + " menu ready: twelve switches; shield Block threshold (0-40), Body Slam threshold (0-50).");
				}
			}
			catch (Exception ex)
			{
				AnimationSettings.Current = current;
				Console.Error.WriteLine("[ShieldOnly] Optional " + text + " menu unavailable; retaining current animation settings: " + ex.GetBaseException().Message);
			}
		}
	}
	internal static class PresentationFlow
	{
		internal static async Task AlongsideAsync(Func<Task> visual, Func<Task> original, Action release, Action<Exception> failed)
		{
			Task presentation = SafelyAsync(visual, failed);
			try
			{
				await original();
				await presentation;
			}
			finally
			{
				release();
				await presentation;
			}
		}

		internal static async Task SafelyAsync(Func<Task> visual, Action<Exception> failed)
		{
			try
			{
				await visual();
			}
			catch (Exception obj)
			{
				failed(obj);
			}
		}

		internal static async Task AroundAsync(Func<Task> before, Func<Task> original, Func<Task> after, Action<Exception> failed)
		{
			await SafelyAsync(before, failed);
			await original();
			await SafelyAsync(after, failed);
		}
	}
