		internal static bool Allows(ICombatState combat, Creature player)
		{
			if (IsSingleplayer && combat.Players.Count == 1 && combat.Players[0].Creature == player)
			{
				Player player2 = player.Player;
				return ((player2 != null) ? ((object)player2.Character).GetType().Name : null) == "Ironclad";
			}
			return false;
		}

		internal static bool AllowsSharedVisual(ICombatState combat, Creature actor)
		{
			Creature actor2 = actor;
			if (!IsSingleplayer)
			{
				if (IsMultiplayer)
				{
					Player player2 = actor2.Player;
					if (((player2 != null) ? ((object)player2.Character).GetType().Name : null) == "Ironclad")
					{
						return combat.Players.Any((Player player) => player.Creature == actor2);
					}
				}
				return false;
			}
			return Allows(combat, actor2);
		}

		internal static bool AllowsBarricade(ICombatState combat, Creature actor)
		{
			if (AllowsSharedVisual(combat, actor))
			{
				if (!IsSingleplayer)
				{
					return LocalContext.IsMe(actor);
				}
				return true;
			}
			return false;
		}

		internal static void Reset(bool clearResources = true)
		{
			OfferingSigilSession.Reset();
			BloodFlowSession.Reset();
			CardHandoff.Cancel();
			SlamSession.Active?.Cancel("presentation-reset");
			ShieldOnly.Slam.PresentationPreloader.Cancel();
			PresentationPreloader.Reset(clearResources);
			MultiplayerPresentationPreloader.Reset(clearResources);
			TurnSession.Active?.Release();
			CardWeapons.Reset();
			CardBodySession.Reset();
			BarricadeSession.Active?.Dispose();
			FeedSession.Reset();
			DemonFormSession.Reset();
			DarkEmbraceSession.Reset();
			BattleTranceHandSession.Reset();
			BrandHandSession.Reset();
			DemonHorns.Reset();
			DefensePolicy.Clear();
